package com.unicare.dispensary.screening;import com.unicare.dispensary.student.*;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class ScreeningService{private final ScreeningRepository screenings;private final StudentRepository students;public ScreeningService(ScreeningRepository a,StudentRepository b){screenings=a;students=b;}@Transactional public ScreeningResponse create(String email,ScreeningRequest r){Student s=students.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found."));return ScreeningResponse.from(screenings.save(new HealthScreening(s,r.date(),clean(r.allergies()),clean(r.conditions()),clean(r.currentMedication()),r.wellbeing(),clean(r.symptoms()),clean(r.notes()))));}@Transactional(readOnly=true)public List<ScreeningResponse> mine(String email){Student s=students.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found."));return screenings.findByStudentIdOrderByCreatedAtDesc(s.getId()).stream().map(ScreeningResponse::from).toList();}@Transactional(readOnly=true)public List<ScreeningResponse> all(){return screenings.findAllByOrderByCreatedAtDesc().stream().map(ScreeningResponse::from).toList();}private static String clean(String s){return s==null||s.isBlank()?null:s.trim();}}
